package com.kernelpack.boot

/**
 * LZ4 解码的交叉验证向量 —— **由 Python 侧生成，请勿手改**。
 *
 * 生成方式：`ghostlock5x/tests/` 下的脚本从**真实 boot.img**（6.1.145 内核，
 * lz4_legacy 压缩）截取块数据，并用已验证的 Python 解码器算出期望输出。
 * Kotlin 侧只要解出同样的结果，就说明移植没有语义偏差。
 *
 * 真实向量只内嵌"压缩前缀 + 期望 sha256"，避免把 85 KB 的期望输出塞进源码。
 */
internal object Lz4Vectors {

    /** 真实 boot.img 第一个 lz4 块的压缩前缀（1536 字节）。 */
    const val REAL_COMPRESSED_B64 =
        ""

    /** 上面前缀解码后的 sha256（Python 侧算出）。 */
    const val REAL_EXPECTED_SHA256 = "11bdf0390da9a385ce06e9c47acaa401d31d019aaaa544e9f3852a6efae01c07"

    const val REAL_EXPECTED_LENGTH = 70496

    /** 合成 A：字面量 + **重叠匹配**（offset=4 < 匹配长度，必须逐字节复制）。 */
    const val SYNTH_A_COMPRESSED_B64 = "SEFCQ0QEAA=="
    const val SYNTH_A_EXPECTED_B64 = "QUJDREFCQ0RBQkNEQUJDRA=="

    /** 合成 B：**超长匹配**（走 15 + 扩展字节路径）。 */
    const val SYNTH_B_COMPRESSED_B64 = "H1gBAPo="
    const val SYNTH_B_EXPECTED_B64 = ""

    /** 合成 C：**多 sequence 串联**（字面量→匹配→字面量）。 */
    const val SYNTH_C_COMPRESSED_B64 = "yEhFTExPLVdPUkxELQwAgFRBSUxUQUlM"
    const val SYNTH_C_EXPECTED_B64 = "SEVMTE8tV09STEQtSEVMTE8tV09STEQtVEFJTFRBSUw="
}
